// Bundle freshness check. neonic-playback.js is a pure concat of the
// three source files via build-playback.js — no transformations, no
// hand-edits. If this test fails, the bundle has drifted from sources
// (or the build script has been modified); run `node build-playback.js`
// and re-commit.
import test from 'node:test';
import assert from 'node:assert';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const __filename = fileURLToPath(import.meta.url);
const root = path.resolve(path.dirname(__filename), '..');

const SOURCES = [
  'logo-engine-standalone.js',
  'neonic-png.js',
  'neonic-loader.js',
];

const banner =
  '// neonic-playback.js — auto-generated bundle of:\n' +
  SOURCES.map(s => '//   - ' + s).join('\n') + '\n' +
  '// Do not edit this file. Edit the sources and re-run `node build-playback.js`.\n\n';

test('neonic-playback.js matches a fresh concat of its sources', () => {
  const expected = banner + SOURCES
    .map(f => readFileSync(path.join(root, f), 'utf8'))
    .join('\n');
  const actual = readFileSync(path.join(root, 'neonic-playback.js'), 'utf8');
  assert.strictEqual(
    actual, expected,
    'neonic-playback.js is stale. Run `node build-playback.js` and commit.'
  );
});
